using Microsoft.EntityFrameworkCore;

// Cosmos DB project context — EF Core 9 breaking changes applied:
// 1. Discriminator property renamed from "Discriminator" to "$type" by default
// 2. id property no longer contains discriminator prefix
// 3. Sync I/O now throws — must use async methods
class CosmosDbContext : DbContext
{
    public DbSet<Session> Sessions => Set<Session>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Preserve old discriminator property name for existing documents
        modelBuilder.Entity<Session>().HasDiscriminator<string>("Discriminator");

        // Preserve old compound id format ("Session|<key>") for existing documents
        modelBuilder.Entity<Session>().HasRootDiscriminatorInJsonId(true);
    }
}

class Session
{
    public string Id { get; set; } = default!;
    public string Name { get; set; } = default!;
}

